"""Pytest unit tests for solution.classify().

Covers:
  1. Normal values   – clearly below / inside / above the interval.
  2. Boundary values – value equals low, high, or both (degenerate).
  3. Degenerate intervals – low == high, negative numbers, zeros, large magnitudes.
"""

import pytest
from solution import classify


# ────────────────────────── 1. Normal values ──────────────────────────

class TestNormalValues:
    """value is unambiguously outside or inside [low, high]."""

    def test_below_range(self):
        assert classify(2, 5, 10) == -1

    def test_inside_range(self):
        assert classify(7, 5, 10) == 0

    def test_above_range(self):
        assert classify(15, 5, 10) == 1

    def test_negative_values_below(self):
        assert classify(-10, -5, 0) == -1

    def test_negative_values_inside(self):
        assert classify(-3, -5, 0) == 0

    def test_negative_values_above(self):
        assert classify(5, -5, 0) == 1

    def test_large_magnitude(self):
        assert classify(1e9, 0, 1e6) == 1
        assert classify(-1e9, 0, 1e6) == -1


# ────────────────────────── 2. Boundary values ────────────────────────

class TestBoundaryValues:
    """value lands exactly on one or both boundaries."""

    def test_value_equals_low(self):
        assert classify(5, 5, 10) == 0

    def test_value_equals_high(self):
        assert classify(10, 5, 10) == 0

    def test_value_equals_both_low_and_high(self):
        # low == high, so this is also a degenerate case
        assert classify(5, 5, 5) == 0

    def test_zero_boundaries(self):
        assert classify(0, 0, 0) == 0
        assert classify(-1, 0, 0) == -1
        assert classify(1, 0, 0) == 1

    def test_float_boundary(self):
        assert classify(1.5, 1.5, 3.5) == 0
        assert classify(1.4, 1.5, 3.5) == -1
        assert classify(3.6, 1.5, 3.5) == 1


# ────────────────────────── 3. Degenerate intervals ───────────────────

class TestDegenerateIntervals:
    """low == high shrinks the interval to a single point."""

    def test_degenerate_single_point_inside(self):
        assert classify(3, 3, 3) == 0

    def test_degenerate_below(self):
        assert classify(2, 3, 3) == -1

    def test_degenerate_above(self):
        assert classify(4, 3, 3) == 1

    def test_degenerate_with_negatives(self):
        assert classify(-5, -5, -5) == 0
        assert classify(-6, -5, -5) == -1
        assert classify(-4, -5, -5) == 1

    def test_degenerate_with_zeros(self):
        assert classify(0, 0, 0) == 0
        assert classify(-0.0, 0, 0) == 0  # -0.0 == 0 in Python

    def test_degenerate_with_floats(self):
        assert classify(0.1, 0.1, 0.1) == 0
        assert classify(0.09, 0.1, 0.1) == -1
        assert classify(0.11, 0.1, 0.1) == 1


# ────────────────────────── 4. Edge & mixed scenarios ─────────────────

class TestEdgeCases:
    """Additional edge conditions that stress the logic."""

    def test_equal_low_and_high_normal(self):
        assert classify(0, 0, 0) == 0

    def test_wide_interval(self):
        assert classify(0, -1_000_000, 1_000_000) == 0

    def test_single_element_interval_at_extreme(self):
        assert classify(10**18, 10**18, 10**18) == 0

    def test_return_type_is_int(self):
        result = classify(5, 1, 10)
        assert isinstance(result, int)
        assert classify(0, 1, 10) == -1 and isinstance(-1, int)
        assert classify(15, 1, 10) == 1 and isinstance(1, int)

    def test_all_three_returns_exist(self):
        """Verify every branch of the function is exercised."""
        assert classify(0, 1, 10) == -1   # below
        assert classify(5, 1, 10) == 0    # inside
        assert classify(15, 1, 10) == 1   # above

